/*& tenant:'sxlq' */ WITH `publish` AS (SELECT `msg_id`, `effective_time`, `tenant_id`, `tenant_name`, `is_include`, CASE WHEN `is_include` = 1 THEN CASE WHEN locate("##", ifnull(`tenant_id`, "")) > 0 OR ifnull(`tenant_id`, "") = "" THEN 1 ELSE 0 END ELSE CASE WHEN locate("##", ifnull(`tenant_id`, "")) <= 0 THEN 1 ELSE 0 END END AS `include_num` FROM `msg_publish` WHERE `msg_publish`.`tenant` = 'sxlq') SELECT `record`.`id`, `record`.`is_agenda`, `record`.`is_read`, `record`.`template_code`, `user_id`, `record`.`title`, `record`.`msg_content`, `record`.`flag`, `record`.`received_object`, `record`.`created_at`, `record`.`app_url`, `record`.`pc_url`, `record`.`msg_dispose_result`, `record`.`business_data_id`, `template`.`msg_type`, `template`.`is_need_dispose`, `publish`.`effective_time`, `publish`.`tenant_id`, `publish`.`tenant_name`, `publish`.`is_include` FROM `msg_record` AS `record` LEFT JOIN `msg_template` AS `template` ON `record`.`template_code` = `template`.`CODE` LEFT JOIN `publish` ON `record`.`id` = `publish`.`msg_id` WHERE `record`.`is_removed` = 0 AND `record`.`is_status` = 1 AND ifnull(`publish`.`include_num`, 1) > 0 AND `template`.`msg_type` = "sysmsg" AND `record`.`flag` = 1 AND ifnull(`publish`.`tenant_id`, "") = "" AND `record`.`tenant` = 'sxlq' AND `template`.`tenant` = 'sxlq' ORDER BY `created_at` DESC